with with_gaps as (select *, case when lag(paid_at) over (partition by status order by paid_at, id) is null or paid_at > lag(paid_at) over (partition by status order by paid_at, id) + interval '30' day then 1 else 0 end as is_new_session from payments), sessions_payments as (select *, sum(is_new_session) over (partition by status order by paid_at, id rows between unbounded preceding and current row) as burst_id from with_gaps) select method, order_id, min(paid_at) as first_seen, percentile_approx(is_new_session, array(0.25, 0.5, 0.75)) as is_new_session_quartiles from sessions_payments group by method, order_id;
